type ttCollector struct {
	mu       sync.Mutex
	paths    []string
	encoding []string
	headers  []string
}

func (c *ttCollector) handler(w http.ResponseWriter, r *http.Request) {
	_, _ = io.Copy(io.Discard, r.Body)
	c.mu.Lock()
	c.paths = append(c.paths, r.URL.Path)
	c.encoding = append(c.encoding, r.Header.Get("Content-Encoding"))
	c.headers = append(c.headers, r.Header.Get("X-Test"))
	c.mu.Unlock()
	w.Header().Set("Content-Type", "application/x-protobuf")
	w.WriteHeader(http.StatusOK)
}

