type ttKind uint8

func TestTraceOTelAttribute(t *testing.T) {
	cases := []struct {
		in   any
		want attribute.Value
	}{
		{"s", attribute.StringValue("s")},
		{true, attribute.BoolValue(true)},
		{1, attribute.IntValue(1)},
		{int64(2), attribute.Int64Value(2)},
		{int32(3), attribute.Int64Value(3)},
		{1.5, attribute.Float64Value(1.5)},
		{float32(0.5), attribute.Float64Value(0.5)},
		{[]string{"a"}, attribute.StringSliceValue([]string{"a"})},
		{[]bool{true}, attribute.BoolSliceValue([]bool{true})},
		{[]int{1}, attribute.IntSliceValue([]int{1})},
		{[]int64{1}, attribute.Int64SliceValue([]int64{1})},
		{[]float64{1}, attribute.Float64SliceValue([]float64{1})},
		{[]any{}, attribute.StringSliceValue([]string{})},
		{[]any{"a", "b"}, attribute.StringSliceValue([]string{"a", "b"})},
		{[]any{true}, attribute.BoolSliceValue([]bool{true})},
		{[]any{int64(1), 2}, attribute.Int64SliceValue([]int64{1, 2})},
		{[]any{1.5}, attribute.Float64SliceValue([]float64{1.5})},
		{[]any{"a", 1}, attribute.StringValue(`["a",1]`)},
		{[]any{true, 1}, attribute.StringValue(`[true,1]`)},
		{[]any{1, "a"}, attribute.StringValue(`[1,"a"]`)},
		{[]any{1.5, "a"}, attribute.StringValue(`[1.5,"a"]`)},
		{[]any{nil}, attribute.StringValue(`[null]`)},
		{map[string]any{"k": 1}, attribute.StringValue(`{"k":1}`)},
		{ttStringer{}, attribute.StringValue("str")},
		{errors.New("e"), attribute.StringValue("e")},
		{ttKind(7), attribute.Int64Value(7)},
		{int16(-2), attribute.Int64Value(-2)},
		{uint64(1 << 63), attribute.StringValue("9223372036854775808")},
		{nil, attribute.StringValue("null")},
		{make(chan int), attribute.StringValue("")},
	}
	for _, c := range cases {
		got := OTelAttribute("k", c.in)
		if _, isChan := c.in.(chan int); isChan {
			if !strings.HasPrefix(got.Value.AsString(), "0x") {
				t.Errorf("chan: %v", got.Value.Emit())
			}
			continue
		}
		if got.Value != c.want {
			t.Errorf("OTelAttribute(%#v) = %v (%v), want %v", c.in, got.Value.Emit(), got.Value.Type(), c.want.Emit())
		}
	}
	kvs := OTelAttributes(map[string]any{"b": 1, "a": "x"})
	if len(kvs) != 2 || kvs[0].Key != "a" {
		t.Fatalf("OTelAttributes = %v", kvs)
	}
}
